package com.hms.social;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/social/connections") public class SocialConnectionStatusController {private final TenantRepository tenants;private final SocialConnectionRepository connections;public SocialConnectionStatusController(TenantRepository t,SocialConnectionRepository c){tenants=t;connections=c;} @PatchMapping("/{connectionId}") public SocialConnection update(@PathVariable String tenantSlug,@PathVariable UUID connectionId,@Valid @RequestBody UpdateSocialConnectionRequest r){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));SocialConnection c=connections.findById(connectionId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Social connection not found"));connections.updateEnabled(connectionId,tenant,r.enabled());return connections.findById(c.getId()).orElseThrow();}}
